const STORE_KEY = "habitTracker";

const els = {
  todayDate: app.querySelector('[data-role="today-date"]'),
  doneCount: app.querySelector('[data-role="done-count"]'),
  totalCount: app.querySelector('[data-role="total-count"]'),
  statsHint: app.querySelector('[data-role="stats-hint"]'),
  progressTrack: app.querySelector('[data-role="progress-track"]'),
  progressFill: app.querySelector('[data-role="progress-fill"]'),
  form: app.querySelector('[data-role="habit-form"]'),
  input: app.querySelector('[data-role="habit-input"]'),
  formError: app.querySelector('[data-role="form-error"]'),
  list: app.querySelector('[data-role="habit-list"]'),
  listCount: app.querySelector('[data-role="list-count"]'),
  emptyState: app.querySelector('[data-role="empty-state"]'),
  saveError: app.querySelector('[data-role="save-error"]'),
  backdrop: app.querySelector('[data-role="dialog-backdrop"]'),
  dialogDesc: app.querySelector('[data-role="dialog-desc"]'),
  dialogCancel: app.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: app.querySelector('[data-role="dialog-confirm"]')
};

let state = { habits: [] };
let pendingDeleteId = null;

function todayKey() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function todayLabel() {
  const d = new Date();
  const week = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][d.getDay()];
  return d.getFullYear() + "年" + (d.getMonth() + 1) + "月" + d.getDate() + "日 " + week;
}

function normalizeHabit(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const id = typeof source.id === "string" && source.id ? source.id : "h_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8);
  const name = typeof source.name === "string" ? source.name : "";
  const createdAt = typeof source.createdAt === "string" ? source.createdAt : new Date().toISOString();
  const doneDates = Array.isArray(source.doneDates)
    ? source.doneDates.filter((item) => typeof item === "string")
    : [];
  return Object.assign({}, source, { id, name, createdAt, doneDates });
}

function normalizeState(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const habits = Array.isArray(source.habits) ? source.habits.map(normalizeHabit) : [];
  return Object.assign({}, source, { habits });
}

function isDoneToday(habit) {
  return habit.doneDates.indexOf(todayKey()) !== -1;
}

function showFormError(message) {
  if (message) {
    els.formError.textContent = message;
    els.formError.hidden = false;
  } else {
    els.formError.textContent = "";
    els.formError.hidden = true;
  }
}

function showSaveError(message) {
  if (message) {
    els.saveError.textContent = message;
    els.saveError.hidden = false;
  } else {
    els.saveError.textContent = "";
    els.saveError.hidden = true;
  }
}

function renderStats() {
  const total = state.habits.length;
  const done = state.habits.filter(isDoneToday).length;
  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  els.listCount.textContent = "共 " + total + " 个";

  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  els.progressFill.style.width = percent + "%";
  els.progressTrack.setAttribute("aria-valuenow", String(percent));

  if (total === 0) {
    els.statsHint.textContent = "还没有习惯，先添加一个吧";
  } else if (done === total) {
    els.statsHint.textContent = "全部完成，今天很棒！";
  } else {
    els.statsHint.textContent = "还剩 " + (total - done) + " 个待完成";
  }
}

function renderList() {
  els.list.textContent = "";
  const sorted = state.habits.slice().sort((a, b) => {
    if (a.createdAt === b.createdAt) return 0;
    return a.createdAt < b.createdAt ? -1 : 1;
  });

  sorted.forEach((habit) => {
    const done = isDoneToday(habit);
    const li = document.createElement("li");
    li.className = "habit-item" + (done ? " is-done" : "");
    li.dataset.habitId = habit.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "habit-check";
    checkbox.checked = done;
    checkbox.dataset.role = "habit-check";
    checkbox.setAttribute("aria-label", "标记“" + habit.name + "”今天已完成");
    checkbox.addEventListener("change", () => {
      toggleHabit(habit.id);
    });

    const name = document.createElement("span");
    name.className = "habit-name";
    name.textContent = habit.name;

    const meta = document.createElement("span");
    meta.className = "habit-meta";
    meta.textContent = done ? "今天已完成" : "今天未完成";

    const del = document.createElement("button");
    del.type = "button";
    del.className = "btn-delete";
    del.dataset.role = "habit-delete";
    del.textContent = "删除";
    del.setAttribute("aria-label", "删除习惯“" + habit.name + "”");
    del.addEventListener("click", () => {
      openDeleteDialog(habit.id);
    });

    li.appendChild(checkbox);
    li.appendChild(name);
    li.appendChild(meta);
    li.appendChild(del);
    els.list.appendChild(li);
  });

  els.emptyState.hidden = state.habits.length > 0;
}

function render() {
  renderStats();
  renderList();
}

async function persist(nextState, errorMessage) {
  try {
    await appStore.setState(nextState);
    showSaveError("");
    return true;
  } catch (err) {
    showSaveError(errorMessage || "保存失败，请重试。");
    return false;
  }
}

async function toggleHabit(id) {
  const habit = state.habits.find((item) => item.id === id);
  if (!habit) return;

  const key = todayKey();
  const has = habit.doneDates.indexOf(key) !== -1;
  const nextDates = has
    ? habit.doneDates.filter((item) => item !== key)
    : habit.doneDates.concat([key]);

  const nextHabits = state.habits.map((item) =>
    item.id === id ? Object.assign({}, item, { doneDates: nextDates }) : item
  );
  const nextState = Object.assign({}, state, { habits: nextHabits });
  const previous = state;

  state = nextState;
  render();

  const ok = await persist(nextState, "打卡状态保存失败，已恢复原状态。");
  if (!ok) {
    state = previous;
    render();
  }
}

function openDeleteDialog(id) {
  const habit = state.habits.find((item) => item.id === id);
  if (!habit) return;
  pendingDeleteId = id;
  els.dialogDesc.textContent = "确定要删除习惯“" + habit.name + "”吗？删除后无法恢复。";
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  els.backdrop.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  closeDeleteDialog();
  if (!id) return;

  const previous = state;
  const nextState = Object.assign({}, state, {
    habits: state.habits.filter((item) => item.id !== id)
  });

  state = nextState;
  render();

  const ok = await persist(nextState, "删除保存失败，已恢复原状态。");
  if (!ok) {
    state = previous;
    render();
  }
}

async function addHabit(name) {
  const trimmed = name.trim();
  if (!trimmed) {
    showFormError("请输入习惯名称。");
    return;
  }
  const duplicated = state.habits.some((item) => item.name === trimmed);
  if (duplicated) {
    showFormError("已存在同名习惯，请换一个名称。");
    return;
  }

  const habit = normalizeHabit({
    id: "h_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8),
    name: trimmed,
    createdAt: new Date().toISOString(),
    doneDates: []
  });

  const previous = state;
  const nextState = Object.assign({}, state, { habits: state.habits.concat([habit]) });

  state = nextState;
  showFormError("");
  render();

  const ok = await persist(nextState, "新增习惯保存失败，请重试。");
  if (!ok) {
    state = previous;
    render();
    return;
  }
  els.input.value = "";
  els.input.focus();
}

async function init() {
  els.todayDate.textContent = todayLabel();

  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (err) {
    raw = null;
  }

  const loaded = normalizeState(raw);
  if (!loaded || !raw || typeof raw !== "object" || !Object.prototype.hasOwnProperty.call(raw, STORE_KEY)) {
    // 首次打开：从空数据开始，不预置示例习惯
    state = { habits: [] };
    try {
      await appStore.setState(Object.assign({}, raw && typeof raw === "object" ? raw : {}, { [STORE_KEY]: state }));
    } catch (err) {
      showSaveError("初始化保存失败，本次修改可能无法保留。");
    }
  } else {
    state = normalizeState(raw[STORE_KEY]);
  }

  render();

  els.form.addEventListener("submit", async (event) => {
    event.preventDefault();
    await addHabit(els.input.value);
  });

  els.input.addEventListener("input", () => {
    if (!els.formError.hidden) showFormError("");
  });

  els.dialogCancel.addEventListener("click", () => {
    closeDeleteDialog();
  });

  els.dialogConfirm.addEventListener("click", async () => {
    await confirmDelete();
  });

  els.backdrop.addEventListener("click", (event) => {
    if (event.target === els.backdrop) closeDeleteDialog();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !els.backdrop.hidden) closeDeleteDialog();
  });
}

await init();

