:root {
  --bg: #0f172a;
  --bg-soft: #16213c;
  --panel: #1b2745;
  --panel-2: #223055;
  --border: #2f3f68;
  --text: #eef2ff;
  --text-dim: #a8b4d6;
  --accent: #4ade80;
  --accent-strong: #22c55e;
  --accent-soft: rgba(74, 222, 128, 0.16);
  --danger: #f87171;
  --danger-soft: rgba(248, 113, 113, 0.16);
  --radius: 14px;
}

* {
  box-sizing: border-box;
}

#app {
  min-height: 100vh;
  background: radial-gradient(1200px 600px at 15% -10%, #1e2b52 0%, var(--bg) 55%, #0b1120 100%);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  padding: 24px 16px 48px;
}

.app-shell {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.app-title {
  margin: 0;
  font-size: 26px;
  letter-spacing: 1px;
  color: var(--text);
}

.app-subtitle {
  margin: 4px 0 0;
  color: var(--text-dim);
  font-size: 13px;
}

.today-chip {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 14px;
}

.today-chip-label {
  font-size: 12px;
  color: var(--text-dim);
}

.today-chip-date {
  font-size: 14px;
  font-weight: 600;
  color: var(--accent);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 10px 30px rgba(4, 8, 20, 0.35);
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  color: var(--text);
}

.stats-panel {
  background: linear-gradient(160deg, var(--panel-2), var(--panel));
}

.stats-row {
  display: flex;
  align-items: center;
  gap: 16px;
}

.stats-number {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.stats-done {
  font-size: 40px;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
}

.stats-sep {
  font-size: 22px;
  color: var(--text-dim);
}

.stats-total {
  font-size: 22px;
  color: var(--text-dim);
}

.stats-text {
  flex: 1;
  min-width: 0;
}

.stats-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.stats-hint {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--text-dim);
}

.progress-track {
  margin-top: 14px;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent));
  transition: width 0.25s ease;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-width: 0;
}

.field-label {
  font-size: 13px;
  color: var(--text-dim);
}

.field-input {
  width: 100%;
  padding: 11px 13px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--text);
  font-size: 15px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field-input::placeholder {
  color: #7d8ab0;
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.habit-form {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 11px 18px;
  font-size: 15px;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent-strong);
  color: #06210f;
  font-weight: 600;
}

.btn-primary:hover {
  background: var(--accent);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.06);
}

.btn-danger {
  background: var(--danger);
  color: #2a0808;
  font-weight: 600;
}

.btn-danger:hover {
  background: #fca5a5;
}

.form-error {
  margin: 10px 0 0;
  font-size: 13px;
  color: var(--danger);
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.habit-item.is-done {
  border-color: rgba(74, 222, 128, 0.5);
  background: var(--accent-soft);
}

.habit-check {
  width: 22px;
  height: 22px;
  flex: none;
  accent-color: var(--accent-strong);
  cursor: pointer;
}

.habit-name {
  flex: 1;
  min-width: 0;
  font-size: 15px;
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
  text-decoration: line-through;
  text-decoration-color: rgba(74, 222, 128, 0.6);
}

.habit-meta {
  font-size: 12px;
  color: var(--text-dim);
  white-space: nowrap;
}

.btn-delete {
  flex: none;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-dim);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
}

.btn-delete:hover {
  color: var(--danger);
  border-color: var(--danger);
  background: var(--danger-soft);
}

.empty-state {
  margin: 6px 0 0;
  padding: 22px 14px;
  text-align: center;
  font-size: 14px;
  color: var(--text-dim);
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.save-error {
  margin: 0;
  padding: 10px 14px;
  border-radius: 10px;
  background: var(--danger-soft);
  border: 1px solid var(--danger);
  color: #fecaca;
  font-size: 13px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 10, 22, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-desc {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 480px) {
  .habit-form {
    flex-direction: column;
    align-items: stretch;
  }

  .stats-done {
    font-size: 34px;
  }
}
